using System;
using System.Collections.Generic;
using System.Linq;
namespace MK.Verification {
 public static class HumanizationRegression {
  static int checks;static void Assert(bool value,string label){checks++;if(!value)throw new Exception("Humanization: "+label);}
  static bool Up(Native.INPUT e){return e.type==1&&(e.U.ki.dwFlags&2)!=0||e.type==0&&(e.U.mi.dwFlags&4)!=0;}
  public static string Run(){
   checks=InputLayoutRegression.Run();using(var timer=new Native.InputTimer()){timer.Slice(1);timer.Slice(0);try{timer.Slice(11);Assert(false,"unbounded timer slice");}catch(ArgumentOutOfRangeException){Assert(true,"timer slices bounded");}timer.Dispose();timer.Dispose();try{timer.Slice(1);Assert(false,"disposed timer reused");}catch(ObjectDisposedException){Assert(true,"timer disposed");}}Assert(!Server.ShouldHideIdle(true,true,true,20000),"long active input retains its indicator");Assert(Server.ShouldHideIdle(true,false,true,11000),"idle ready state may hide");Assert(!Server.ShouldHideIdle(false,false,true,20000),"closed state does not schedule late idle UI");IntPtr layout=Native.GetKeyboardLayout(0);var typed=new Humanizer(42).Text("aA1?中😀","auto","natural",null,layout);
   Assert(typed.Units.Count==6,"Unicode codepoints are not split");
   var ascii=typed.Units.Take(4).SelectMany(u=>u.Steps).SelectMany(s=>s.Inputs).ToArray();Assert(ascii.All(e=>e.type==1&&(e.U.ki.dwFlags&4)==0),"auto ASCII uses mapped keys on every target");
   Assert(ascii.Where(e=>e.U.ki.wVk!=16).All(e=>(e.U.ki.dwFlags&8)!=0&&e.U.ki.wScan!=0),"ASCII main keys carry real scan code fields");
   var scanHeld=new OwnedInputs();var original=ascii.First(e=>e.U.ki.wVk!=16&&!Up(e));scanHeld.Record(new[]{original},1);scanHeld.Release(e=>{Assert(e.U.ki.wScan==original.U.ki.wScan&&(e.U.ki.dwFlags&8)!=0&&Up(e),"cleanup preserves original scan and flags");return 1;},key=>false);
   Assert(typed.Units[4].Steps.SelectMany(s=>s.Inputs).All(e=>(e.U.ki.dwFlags&4)!=0),"non ASCII stays Unicode");Assert(typed.Units[5].Steps.Count==1&&typed.Units[5].Steps[0].Inputs.Length==4,"surrogates atomic");
   Assert(typed.Units.SelectMany(u=>u.Steps).SelectMany(s=>s.Inputs).All(e=>e.U.ki.dwExtraInfo.ToUInt64()==(ulong)Native.Marker),"injection marker unchanged");
   var unicode=new Humanizer(3).Text("abc","unicode","off",null,layout);Assert(unicode.Units.SelectMany(u=>u.Steps).SelectMany(s=>s.Inputs).All(e=>(e.U.ki.dwFlags&4)!=0),"explicit Unicode mode retained");
   try{new Humanizer(0).Text("a中","scancode","natural",null,layout);Assert(false,"unsupported accepted");}catch(Failure e){Assert(e.Code=="UNSUPPORTED_INPUT","scancode entire request rejected");}
   var gaps=new List<double>();for(int seed=0;seed<120;seed++){var plan=new Humanizer(seed).Text(String.Concat(Enumerable.Repeat("ab",32)),"auto","natural",null,layout);double at=0,prior=-1;foreach(var unit in plan.Units)foreach(var step in unit.Steps){at+=step.DelayBeforeMs;foreach(var input in step.Inputs)if(input.U.ki.wVk>=65&&input.U.ki.wVk<=90&&!Up(input)){if(prior>=0)gaps.Add(at-prior);prior=at;}}}
   var sorted=gaps.OrderBy(x=>x).ToArray();double median=sorted[sorted.Length/2],mean=gaps.Average(),sd=Math.Sqrt(gaps.Select(x=>(x-mean)*(x-mean)).Average()),p95=sorted[(int)(sorted.Length*.95)],p99=sorted[(int)(sorted.Length*.99)];Assert(median>=110&&median<=130,"natural median 110-130ms");Assert(p95>=400&&p95<=900&&p99>=800,"explicit heavy tail");Assert(1000/mean>=4&&1000/mean<=8,"planned average 4-8 chars per second");
   var clustered=new Humanizer(91).Text(String.Concat(Enumerable.Repeat("ab",32)),"auto","natural",null,layout);var intervals=new List<int>();int previousHold=0;for(int i=0;i<clustered.Units.Count;i++){var unit=clustered.Units[i];if(i>0)intervals.Add(previousHold+unit.Steps[0].DelayBeforeMs);previousHold=unit.Steps.Skip(1).Sum(s=>s.DelayBeforeMs);}Assert(intervals.Count(x=>x>=350)>=7&&intervals.Count(x=>x<200)>=35,"burst and pause modes both present");
   var plain=new Humanizer(91).Text("ab","unicode","natural",null,layout);foreach(string context in new[]{" a",".a","aA","aa"}){var modulated=new Humanizer(91).Text(context,"unicode","natural",null,layout);Assert(modulated.DelayMs>plain.DelayMs,"context adds a bounded pause");}
   var off=new Humanizer(4).Text("PageFaultTest","auto","off",0,layout);Assert(off.DelayMs==0&&off.Units.All(u=>u.Steps.Count==1),"maxSpeed deterministic");
   var combo=new Humanizer(8).Key("Ctrl+A","natural");Assert(combo.Units[0].Steps.Count==4,"combo events separated");Assert(combo.Units[0].Steps[1].DelayBeforeMs>=10&&combo.Units[0].Steps[1].DelayBeforeMs<=40,"modifier lead");
   var bounds=new Native.RECT{Left=-1920,Top=-100,Right=3840,Bottom=2160};var target=new Native.RECT{Left=800,Top=300,Right=820,Bottom=320};int over=0;var holds=new HashSet<int>();int longest=0;
   for(int seed=0;seed<100;seed++){var start=new Native.POINT{X=-800,Y=100};var expected=new Native.POINT{X=810,Y=310};var motion=new Humanizer(seed).MovePath(start,expected,bounds,target,"natural",true);if(motion.Overshoot)over++;holds.Add(motion.HoldMs);longest=Math.Max(longest,motion.Frames.Count);Assert(motion.Frames.Count>90&&motion.Frames.Count<=201,"long-path frames scale with duration, no 90-frame cap");Assert(motion.DelayMs-motion.HoldMs>=600&&motion.DelayMs-motion.HoldMs<=1600,"movement duration excludes click hold");Assert(motion.Frames.Sum(f=>f.DelayBeforeMs)==motion.DelayMs-motion.HoldMs,"deadlines match the complete motion budget");Assert(motion.HoldMs>=60&&motion.HoldMs<=120,"mouse hold");Assert(Math.Abs(motion.Target.X-expected.X)<=2&&Math.Abs(motion.Target.Y-expected.Y)<=2,"safe endpoint jitter");var prior=start;foreach(var frame in motion.Frames){Assert(frame.Point.X>=bounds.Left&&frame.Point.X<bounds.Right&&frame.Point.Y>=bounds.Top&&frame.Point.Y<bounds.Bottom,"virtual bounds");prior=frame.Point;}Assert(prior.X==motion.Target.X&&prior.Y==motion.Target.Y,"exact planned endpoint");}
   Assert(over>=15&&over<=50&&holds.Count>10,"varied holds and bounded overshoot probability");
   var representative=new Humanizer(6).MovePath(new Native.POINT{X=500,Y=310},new Native.POINT{X=810,Y=310},bounds,target,"natural",false);var steps=new List<double>();var prev=new Native.POINT{X=500,Y=310};foreach(var frame in representative.Frames){steps.Add(Math.Sqrt(Math.Pow(frame.Point.X-prev.X,2)+Math.Pow(frame.Point.Y-prev.Y,2)));prev=frame.Point;}steps.Sort();Assert(steps[steps.Count/2]>=3&&steps[steps.Count/2]<=12,"representative 310px path density");
   double referenceHz=0,referenceStep=0;int referenceFrames=0;
   foreach(int distance in new[]{310,1000,2000})for(int seed=0;seed<100;seed++){
    var start=new Native.POINT{X=810-distance,Y=310};var motion=new Humanizer(seed).MovePath(start,new Native.POINT{X=810,Y=310},bounds,target,"natural",false);var delta=new List<double>();var prior=start;
    foreach(var frame in motion.Frames){delta.Add(Math.Sqrt(Math.Pow(frame.Point.X-prior.X,2)+Math.Pow(frame.Point.Y-prior.Y,2)));prior=frame.Point;}delta.Sort();double stepMedian=delta[delta.Count/2],span=motion.Frames.Sum(f=>f.DelayBeforeMs)-motion.Frames[0].DelayBeforeMs,hz=1000*motion.Frames.Count/span;
    Assert(span>=600&&span<=1600,"reference first-to-last movement span");Assert(hz>=110&&hz<=130,"reference effective 110-130Hz");Assert(stepMedian>=3&&stepMedian<=12,"reference median step 3-12px");
    if(distance==2000&&seed==6){referenceHz=hz;referenceStep=stepMedian;referenceFrames=motion.Frames.Count;}
   }
   var veryLong=new Humanizer(6).MovePath(new Native.POINT{X=-1800,Y=310},new Native.POINT{X=3000,Y=310},bounds,new Native.RECT{Left=2990,Top=300,Right=3010,Bottom=320},"natural",false);Assert(veryLong.Frames.Count>201&&veryLong.DelayMs-veryLong.HoldMs>1600,"exceptional distance stretches time to preserve density");
   Assert(new Humanizer(6).MovePath(new Native.POINT{X=810,Y=310},new Native.POINT{X=810,Y=310},bounds,target,"natural",false).Frames.Count==1,"zero distance cannot create fake sampling motion");
   long clock=0;int emitted=0;Humanizer.RunMotion(representative,p=>{emitted++;clock+=3;},ms=>clock+=ms,()=>clock+=2,()=>clock);Assert(emitted==representative.Frames.Count&&clock<=representative.DelayMs-representative.HoldMs+10,"deadlines absorb validation and send overhead");
   clock=0;emitted=0;int wake=0;Humanizer.RunMotion(representative,p=>{emitted++;clock++;},ms=>{clock+=ms+(wake++%2);},()=>{},()=>clock);Assert(emitted==representative.Frames.Count,"1ms timer jitter must not halve 125Hz into 62Hz");
   clock=0;emitted=0;Humanizer.RunMotion(representative,p=>{emitted++;clock+=100;},ms=>clock+=ms,()=>{},()=>clock);Assert(emitted<representative.Frames.Count,"late frames are not replayed in a burst");
   for(int stop=0;stop<representative.Frames.Count;stop++){clock=0;emitted=0;try{Humanizer.RunMotion(representative,p=>{Assert(emitted<stop,"no motion after cancellation");emitted++;},ms=>clock+=ms,()=>{if(emitted==stop)throw new Failure("USER_STOPPED");},()=>clock);Assert(false,"motion cancellation ignored");}catch(Failure e){Assert(e.Code=="USER_STOPPED"&&emitted==stop,"each motion boundary is cancellable");}}
   var immediate=new Humanizer(6).MovePath(new Native.POINT{X=500,Y=310},new Native.POINT{X=810,Y=310},bounds,target,"off",true);Assert(immediate.Frames.Count==1&&immediate.DelayMs==0&&immediate.HoldMs==0&&immediate.Target.X==810,"maxSpeed skips motion randomness and holds");
   var point=new Native.POINT{X=810,Y=310};var exact=new Humanizer(1).MovePath(point,point,bounds,target,"natural",false);Assert(exact.Target.X==point.X&&exact.Target.Y==point.Y,"pixel coordinates are not jittered blindly");
   try{new Humanizer(1).Text(new String('a',16000),"auto","natural",null,layout);Assert(false,"budget accepted");}catch(Failure e){Assert(e.Code=="HUMANIZE_BUDGET_EXCEEDED"&&e.Execution=="not_sent","long slow text rejected before input");}
   // Fail at every scheduled boundary, then run the real ownership cleanup with an inert sink.
   for(int fail=0;fail<4;fail++){var owned=new OwnedInputs();var sent=new List<Native.INPUT>();int step=0;try{Humanizer.Run(combo.Units[0],events=>{if(step++==fail)throw new Failure("USER_STOPPED");owned.Record(events,events.Length);sent.AddRange(events);},ms=>{},()=>{});}catch(Failure){}finally{owned.Release(e=>{Assert(Up(e),"cleanup only releases owned events");sent.Add(e);return 1;},key=>false);}Assert(owned.Count==0,"no stuck modifiers after cancellation");}
   var mouse=new OwnedInputs();mouse.Record(new[]{Native.Mouse(2)},1);Assert(mouse.OwnsVirtual(1),"own held button is not USER_BUSY");int releases=0;mouse.Release(e=>{releases++;Assert((e.U.mi.dwFlags&4)!=0,"mouse release");return 1;},key=>false);Assert(releases==1&&mouse.Count==0,"held click released on failure");
   mouse.Record(new[]{Native.Mouse(2)},1);mouse.Release(e=>{Assert(false,"released physical button");return 1;},key=>key==1);Assert(mouse.Count==0,"physical takeover does not release user input");
   var broken=new OwnedInputs();broken.Record(new[]{Native.Key(16,false),Native.Key(65,false)},2);int attempted=0;try{broken.Release(e=>{attempted++;return e.U.ki.wVk==16?0u:1u;},key=>false);Assert(false,"cleanup failure accepted");}catch(Failure e){Assert(e.Code=="CONTROL_CLOSE_FAILED"&&attempted==2&&broken.Count==1,"partial cleanup remains unconfirmed and tries remaining keys");}broken.Release(e=>1,key=>false);Assert(broken.Count==0,"cleanup retry sends only releases");
   var editor=Native.D("runtimeId","editor","editable",true,"enabled",true,"password",false,"value","headTAIL","selectionStart",4,"selectionEnd",4);
   const string prose="ordinary prose with several words for a controlled typing test";
   Assert(Humanizer.TypoEligible("Notepad.exe","Untitled",editor,prose),"known readable editor eligible");foreach(string app in new[]{"cmd.exe","powershell.exe","WindowsTerminal.exe","Code.exe","chrome.exe","unknown.exe"})Assert(!Humanizer.TypoEligible(app,"Untitled",editor,prose),"terminal/browser/unknown excluded");
   Assert(!Humanizer.TypoEligible("Notepad.exe","script.ps1",editor,prose)&&!Humanizer.TypoEligible("Notepad.exe","Untitled",editor,"git status"),"script documents and commands excluded");
   Func<char,IntPtr,Native.ScanKey> mapped=(c,l)=>new Native.ScanKey{Vk=(ushort)Char.ToUpperInvariant(c),Scan=(ushort)c};int correctedPlans=0;
   for(int seed=0;seed<80;seed++){
    var plan=new Humanizer(seed,mapped).Text(prose,"auto","natural",null,new IntPtr(0x409),5);var value=new System.Text.StringBuilder("headTAIL");int caret=4,completed=0,typoCount=0;var owned=new OwnedInputs();
    foreach(var unit in plan.Units){
     if(unit.Correction){var current=Native.D("runtimeId","editor","value",value.ToString(),"selectionStart",caret,"selectionEnd",caret);Assert(Humanizer.CorrectionMatches(editor,current,prose,unit),"readback matches only the owned wrong character");current["value"]="changed";Assert(!Humanizer.CorrectionMatches(editor,current,prose,unit),"unrelated content change blocks Backspace");current["value"]=value.ToString();current["selectionStart"]=caret+1;Assert(!Humanizer.CorrectionMatches(editor,current,prose,unit),"caret change blocks Backspace");}
     Humanizer.Run(unit,events=>{owned.Record(events,events.Length);foreach(var e in events)if(e.type==1&&!Up(e)&&e.U.ki.wVk!=16){if(e.U.ki.wVk==8){value.Remove(--caret,1);}else{char c=(char)e.U.ki.wVk;c=Char.ToLowerInvariant(c);value.Insert(caret++,c);}}},ms=>{},()=>{});completed+=unit.CodePoints;if(unit.IsTypo)typoCount++;
    }
    Assert(typoCount<=2&&plan.Units.Count(u=>u.Correction)==typoCount,"at most two one-character correction sequences");Assert(value.ToString()=="head"+prose+"TAIL","final value exactly equals requested insertion");Assert(completed==prose.Length+typoCount,"extra inserted letters count in sentCodePoints");Assert(owned.Count==0,"corrections leave no held keys");if(typoCount>0)correctedPlans++;
   }
   Assert(correctedPlans>60,"fixed-seed samples exercise real correction plans");
   foreach(var mode in new[]{"unicode","off","non-us"}){var plan=new Humanizer(2,mapped).Text(prose,mode=="unicode"?"unicode":"auto",mode=="off"?"off":"natural",null,new IntPtr(mode=="non-us"?0x804:0x409),5);Assert(!plan.Units.Any(u=>u.IsTypo||u.Correction),"Unicode, maxSpeed and non-US layouts do not synthesize errors");}
   var withCorrections=new Humanizer(2,mapped).Text(prose,"auto","natural",null,new IntPtr(0x409),5);var correctionUnit=withCorrections.Units.First(u=>u.Correction);
   for(int fail=0;fail<correctionUnit.Steps.Count;fail++){var owned=new OwnedInputs();int sends=0;try{Humanizer.Run(correctionUnit,events=>{if(sends==fail)throw new Failure("USER_STOPPED");sends++;owned.Record(events,events.Length);},ms=>{},()=>{});}catch(Failure){}finally{owned.Release(e=>{Assert(Up(e),"cancelled correction only releases owned input");return 1;},key=>false);}Assert(sends==fail&&owned.Count==0,"correction interruption does not replay or type the remaining text");}
   var normalGaps=new List<int>();var punctuationGaps=new List<int>();for(int seed=0;seed<200;seed++){var baselinePlan=new Humanizer(seed).Text("ab","unicode","natural",null,layout);var punct=new Humanizer(seed).Text(".b","unicode","natural",null,layout);normalGaps.Add(baselinePlan.Units[0].Steps.Skip(1).Sum(x=>x.DelayBeforeMs)+baselinePlan.Units[1].Steps[0].DelayBeforeMs);punctuationGaps.Add(punct.Units[0].Steps.Skip(1).Sum(x=>x.DelayBeforeMs)+punct.Units[1].Steps[0].DelayBeforeMs);}normalGaps.Sort();punctuationGaps.Sort();Assert(punctuationGaps[100]-normalGaps[100]>=60,"punctuation-group P50 exceeds plain group by at least 60ms");
   int began=0,ended=0;foreach(int fault in new[]{0,1,2}){try{using(var lease=new Native.TimerResolution(ms=>{Assert(ms==1,"1ms request");began++;return 0;},ms=>{Assert(ms==1,"matching release period");ended++;return 0;})){if(fault>0)throw new Failure("USER_STOPPED");}}catch(Failure){}}Assert(began==3&&ended==3,"timer request/release paired for normal and cancelled exits");
   int failedEnd=0;using(var failed=new Native.TimerResolution(ms=>97,ms=>{failedEnd++;return 0;})){Assert(!failed.Acquired&&failed.Released,"failed acquisition is not a lease");}Assert(failedEnd==0,"no unmatched release after failed begin");
   var repeated=new Native.TimerResolution(ms=>0,ms=>{failedEnd++;return 0;});repeated.Dispose();repeated.Dispose();Assert(failedEnd==1&&repeated.Released,"release is idempotent");var brokenLease=new Native.TimerResolution(ms=>0,ms=>97);brokenLease.Dispose();Assert(!brokenLease.Released,"release failure remains visible");
   var realTiming=new Native.TimerResolution();var waits=new List<double>();var cpuStart=System.Diagnostics.Process.GetCurrentProcess().TotalProcessorTime;var elapsed=System.Diagnostics.Stopwatch.StartNew();try{using(var wait=new Native.InputTimer()){for(int i=0;i<30;i++){var stamp=System.Diagnostics.Stopwatch.StartNew();wait.Slice(8);waits.Add(stamp.Elapsed.TotalMilliseconds);}}}finally{realTiming.Dispose();}elapsed.Stop();double cpuMs=(System.Diagnostics.Process.GetCurrentProcess().TotalProcessorTime-cpuStart).TotalMilliseconds;waits.Sort();Assert(realTiming.Released,"native 1ms lease released after inert timer probe");
   return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(Native.D("ok",true,"mode","planner-and-inert-sink","assertions",checks,"checkedCaseIds",new[]{"HUM-02","HUM-03","HUM-04","HUM-05","HUM-06","HUM-08","HUM-09","HUM-10","LAYOUT-01"},"plannedMedianMs",median,"plannedP95Ms",p95,"plannedP99Ms",p99,"plannedSdMs",Math.Round(sd,2),"plannedCharsPerSecond",Math.Round(1000/mean,2),"maximumMotionFrames",longest,"reference2000pxFrames",referenceFrames,"reference2000pxHz",Math.Round(referenceHz,2),"reference2000pxMedianStep",Math.Round(referenceStep,2),"correctedPlans",correctedPlans,"punctuationP50ExtraMs",punctuationGaps[100]-normalGaps[100],"inertTimerProbe",Native.D("acquired",realTiming.Acquired,"released",realTiming.Released,"waitMedianMs",Math.Round(waits[waits.Count/2],2),"wallMs",Math.Round(elapsed.Elapsed.TotalMilliseconds,2),"cpuMs",cpuMs),"desktopObserved",false,"inputSent",false,"physicalProbe","NOT_RUN"));
  }
 }
}
